def digest(path):
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def clean(value):
    if isinstance(value, dict):
        return {str(k): clean(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [clean(v) for v in value]
    if isinstance(value, np.generic):
        return clean(value.item())
    if isinstance(value, float) and not np.isfinite(value):
        return None
    return value


def write_json(path, value):
    path.write_text(json.dumps(clean(value), ensure_ascii=False, indent=2, allow_nan=False), encoding="utf-8")


def numeric(series):
    # Conversao somente em memoria, com prova de que nao descarta valores.
    if pd.api.types.is_bool_dtype(series.dtype):
        return None
    out = pd.to_numeric(series, errors="coerce")
    if int(out.notna().sum()) != int(series.notna().sum()):
        return None
    return out.astype(float)


def load(path):
    with path.open(encoding="utf-8-sig", newline="") as f:
        head = next(csv.reader(f))
    assert len(head) == len(set(head)), f"Cabecalho duplicado: {path}"
    df = pd.read_csv(path, encoding="utf-8-sig", low_memory=False)
    assert list(df) == head
    for key in KEY:
        values = pd.to_numeric(df[key], errors="raise")
        assert values.notna().all() and (values == values.round()).all(), key
        df[key] = values.astype("int64")
    assert not df.duplicated(KEY).any(), f"Chave nao unica: {path}"
    return df


def profile(df):
    result = {}
    for col in df:
        s = df[col]
        valid = s.notna()
        n = numeric(s)
        per_mun = df.groupby("codigo_ibge")[col].nunique(dropna=True)
        per_year = df.groupby("ano")[col].nunique(dropna=True)
        result[col] = {
            "dtype": str(s.dtype), "validos": int(valid.sum()),
            "ausentes": int((~valid).sum()), "proporcao_ausente": float((~valid).mean()),
            "distintos": int(s.nunique(dropna=True)),
            "zeros_numericos": int((n == 0).sum()) if n is not None else None,
            "infinitos": int(np.isinf(n).sum()) if n is not None else 0,
            "ano_min": int(df.loc[valid, "ano"].min()) if valid.any() else None,
            "ano_max": int(df.loc[valid, "ano"].max()) if valid.any() else None,
            "anos_com_valor": int(df.loc[valid, "ano"].nunique()),
            "municipios_com_valor": int(df.loc[valid, "codigo_ibge"].nunique()),
            "min": float(n.min()) if n is not None and valid.any() else None,
            "max": float(n.max()) if n is not None and valid.any() else None,
            "constante_no_municipio": bool((per_mun <= 1).all()),
            "comum_no_ano": bool((per_year <= 1).all()),
            "valores_textuais": sorted(map(str, s.dropna().unique())) if n is None and s.nunique() <= 12 else [],
        }
    return result


def compare(a, b, exact=False):
    # Vetores ja alinhados. Nao preenche NA. Tolerancia simetrica.
    a, b = a.reset_index(drop=True), b.reset_index(drop=True)
    ma, mb = a.isna(), b.isna()
    both = ~(ma | mb)
    na, nb = numeric(a), numeric(b)
    if na is not None and nb is not None:
        av, bv = na[both].to_numpy(), nb[both].to_numpy()
        finite = np.isfinite(av) & np.isfinite(bv)
        eq = av == bv
        delta = np.abs(av - bv)
        scale = np.maximum(np.abs(av), np.abs(bv))
        close = eq if exact else eq | (finite & (delta <= ATOL + RTOL * scale))
        max_abs = float(delta[finite].max()) if finite.any() else None
        max_rel = float((delta[finite] / np.maximum(scale[finite], np.finfo(float).tiny)).max()) if finite.any() else None
    else:
        eq = (a[both].astype(str).to_numpy() == b[both].astype(str).to_numpy())
        close = eq
        max_abs = max_rel = None
    return {
        "comparaveis": int(both.sum()), "dif_exatas": int((~eq).sum()),
        "dif_tolerancia": int((~close).sum()), "ausencia_xor": int((ma ^ mb).sum()),
        "so_a_presente": int((~ma & mb).sum()), "so_b_presente": int((ma & ~mb).sum()),
        "ambos_ausentes": int((ma & mb).sum()), "max_abs": max_abs, "max_rel": max_rel,
        "distintos_a_comuns": int(a[both].nunique()), "distintos_b_comuns": int(b[both].nunique()),
    }


def candidate_pairs(pt, gm):
    pairs = []
    def add(p, g, concept, evidence, mode="identity", factor=1.0, compatible=True):
        if p in pt and g in gm:
            pairs.append(dict(pt=p, gm=g, conceito=concept, evidencia=evidence,
                              modo=mode, fator=factor, mesmo_conceito=compatible))
    source = "AED/gm/build_consolidated_panel_notebook.py e catalogo PT incorporado"
    for col in sorted(set(pt) & set(gm)):
        add(col, col, col, source)
    for product, gp in [("soja", "soja"), ("milho", "milho"), ("carne_bovina", "carne")]:
        add(f"preco_nominal_media_anual__{product}", f"p{gp}_media_anual", "preco mundial nominal medio do ano", source)
        add(f"ln_preco_nominal_media_anual__{product}", f"p{gp}_media_anual", "preco nominal: exponencial do log PT", source, "exp")
        add(f"preco_nominal_media_anual_lag1__{product}", f"p{gp}_lag1", "preco anterior: ano civil PT / janela sazonal GM", source)
        add(f"ln_preco_nominal_media_anual_lag1__{product}", f"ln_p{gp}_lag1", "log preco anterior: janelas diferentes", source)
    for product, gprod in [("soja", "soja"), ("milho", "milho")]:
        raw = next((c for c in pt if c.startswith("rendimento_medio_kg_ha__" + product.title())), None)
        lag = next((c for c in pt if c.startswith("rendimento_medio_kg_ha_lag1__" + product.title())), None)
        if raw: add(raw, f"rend_{gprod}_kg_ha", "rendimento PAM observado", source)
        if lag: add(lag, f"rend_{gprod}_lag1", "rendimento PAM anterior", source)
        add(f"capacidade_valor__{product}__pam_1991_2000_min7", f"hprod_{gprod}_pre2001", "media historica PAM: criterios diferentes", source)
    for raster in ["sxHr0_mze", "sxHr0_soy", "sxLr0_mze", "sxLr0_soy", "yxHr0_mze", "yxHr0_soy", "yxLr0_mze", "yxLr0_soy"]:
        prod = "milho" if raster.endswith("mze") else "soja"
        add(f"capacidade_valor__{prod}__gaez_{raster}", raster, "GAEZ mesma variante, geografia distinta", source)
    for prod, suffix in [("soja", "soy"), ("milho", "mze")]:
        add(f"capacidade_valor__{prod}__gaez_yxHr0_{suffix}", f"gaez_yield_{prod}_comercial_kg_ha", "GAEZ: materia seca /0.87 no GM", source, "scale", 1/0.87)
        add(f"capacidade_valor__{prod}__gaez_sxHr0_{suffix}", f"aptidao_{prod}_norm", "GAEZ sx /10000 no GM", source, "scale", 1/10000)
    for dest in ["agricultura", "pastagem"]:
        add(f"{dest}_ha", f"estoque_{dest}_ha", "estoque do destino, classes diferentes a conferir", source)
        add(f"conversao_ha__{dest}", f"Y_conv_{dest}_ha", "PT transicao nativa / GM incremento liquido positivo", source, compatible=False)
    add("nativa_ha", "native_veg_ha_it", "estoque de vegetacao nativa", source)
    add("nativa_ha_lag1", "native_veg_ha_lag1", "estoque nativo anterior recomposto PT / candidato GM", source)
    add("area_referencia_ha", "area_mapeada_ha", "area de referencia estatica PT / area anual mapeada GM", source)
    add("lotacao_cabecas_ha", "lotacao_winsorizada", "lotacao bruta PT / truncada [0,4] GM", source, "clip_0_4")
    add("efetivo_bovino_lag1", "ln_bovino_lag1", "rebanho anterior: log1p; tratamento de ausentes diferente", source,"log1p")
    add("precip_mm_anual", "precip_total_anual_mm", "CHIRPS anual, geografia/completude diferentes", source)
    add("n_autos_observados__ibama_informada", "n_autos_ibama_it", "autos informados: regras de identidade/cobertura diferentes", source)
    add("n_autos_observados__ibama_espacial", "n_autos_ibama_espacial", "autos espaciais: geografia/identidade diferentes", source)
    add("n_autos_observados__ibama_espacial", "n_autos_espacial", "autos espaciais: GM imputado zero", source)
    add("interacao_ln_preco_real_usd2024_media_anual_lag1_capacidade_z__soja__gaez_sxHr0_soy", "choque_preco_soja_aptidao", "exposicao preco x aptidao: deflacao, janela e escala distintas", source)
    # Remove somente duplicatas de pares/modo, sem suprimir correspondencias multiplas.
    return list({(r["pt"],r["gm"],r["modo"]):r for r in pairs}.values())


def pair_results(pt, gm):
    results = []
    for item in candidate_pairs(pt, gm):
        a, b = pt[item["pt"]], gm[item["gm"]]
        if item["modo"] == "scale": a = a * item["fator"]
        elif item["modo"] == "clip_0_4": a = a.clip(0,4)
        elif item["modo"] == "exp": a = np.exp(a)
        elif item["modo"] == "log1p": a = np.log1p(a)
        exact = item["pt"] in KEY or item["gm"].startswith("n_autos") or item["pt"] == "efetivo_bovino"
        metrics = compare(a, b, exact=exact)
        informative = metrics["comparaveis"] >= 30 and min(metrics["distintos_a_comuns"],metrics["distintos_b_comuns"]) >= 2
        equal = metrics["dif_tolerancia"] == 0 and metrics["ausencia_xor"] == 0
        if not item["mesmo_conceito"]:
            category = "e"  # correspondencia conceitual rejeitada: fluxo vs variacao de estoque
        elif item["pt"] == "area_referencia_ha":
            category = "c"  # tratamento estatico/anual distinto apesar da proximidade numerica
        elif equal and informative:
            category = "a" if item["modo"] == "identity" else "b"
        elif item["mesmo_conceito"]:
            category = "c"
        else: category = "e"
        results.append({**item, **metrics, "categoria": category})
    return results


def numerical_scan(pt, gm, mapped):
    # Busca exaustiva de coincidencias; nao atribui conceito por valores.
    known = {(r["pt"],r["gm"]) for r in mapped}
    pnum = {c:numeric(pt[c]) for c in pt}
    gnum = {c:numeric(gm[c]) for c in gm}
    hits = []
    tested = 0
    for p,a in pnum.items():
        if a is None: continue
        av = a.to_numpy()
        for g,b in gnum.items():
            if b is None: continue
            tested += 1
            bv = b.to_numpy()
            mask = np.isfinite(av) & np.isfinite(bv)
            if not mask.any(): continue
            delta = np.abs(av[mask]-bv[mask])
            if np.all(delta <= ATOL + RTOL*np.maximum(np.abs(av[mask]),np.abs(bv[mask]))):
                m = compare(a,b,exact=p in KEY or g in KEY)
                hits.append({"pt":p,"gm":g,**m,"mapeado":(p,g) in known,
                             "categoria":"mapeado" if (p,g) in known else "d",
                             "evidencia_insuficiente":m["comparaveis"]<30 or min(m["distintos_a_comuns"],m["distintos_b_comuns"])<2})
    return tested,hits


def formula_tests(pt, gm):
    tests = []
    def test(base, label, actual, expected, exact=False):
        m=compare(actual,expected,exact)
        tests.append({"base":base,"teste":label,**m,
                      "resultado":"confere" if m["dif_tolerancia"]==0 and m["ausencia_xor"]==0 else "diverge"})
    for dest in ["agricultura","pastagem"]:
        stock=gm[f"estoque_{dest}_ha"]
        actual=gm[f"Y_conv_{dest}_ha"].where(gm.ano>gm.ano.min())
        test("GM",f"Y_{dest}=max(diff estoque,0), apenas 2002-2024",actual,stock.groupby(gm.codigo_ibge).diff().clip(lower=0))
        test("GM",f"Y_{dest}=max(delta armazenado,0), todos anos",gm[f"Y_conv_{dest}_ha"],gm[f"delta_{dest}_ha"].clip(lower=0))
    test("GM","Y_total=soma incrementos positivos",gm.Y_conv_total_ha,gm.Y_conv_agricultura_ha+gm.Y_conv_pastagem_ha)
    test("GM","taxa GM total/denominador>100 clip[0,1]",gm.Y_tx_conv,(gm.Y_conv_total_ha/gm.native_veg_ha_lag1.where(gm.native_veg_ha_lag1>100)).clip(0,1))
    test("GM","autos lag com zero inicial",gm.n_autos_lag1,gm.n_autos_ibama_it.groupby(gm.codigo_ibge).shift(1).fillna(0),True)
    test("GM","estoque embargo=cumsum desde 2001",gm.estoque_embargado_acum_ha,gm.area_embargada_nova_ha.groupby(gm.codigo_ibge).cumsum())
    test("GM","dummy relevo=amplitude<250",gm.dummy_relevo_plano,(gm.amplitude_altimetrica_m<250).astype(int),True)
    for dest in ["agricultura","pastagem"]:
        test("PT",f"taxa {dest}=conversao/nativa inicial",pt[f"taxa_conversao__{dest}"],pt[f"conversao_ha__{dest}"]/pt.y_nativa_inicial_ha.where(pt.y_nativa_inicial_ha>0))
    test("PT","NA de Y coincide com area invalida positiva",pt.conversao_ha__agricultura.isna(),pt.y_area_nao_valida_par_ha.gt(0),True)
    return tests


def source_tests(root, here, pt, gm):
    """Testes independentes de linhagem; le fontes locais, sem produtor."""
    result={"originais":[],"linhagem":{},"territorio":{}}
    base=root/"2_INTI/xdata/chap1/processed/tabular"
    for file, value, product in [
        ("h1_h2__pam_soja_milho__ibge__municipio_anual.csv","rendimento_medio_kg_ha","milho"),
        ("h1_h2__pam_soja_milho__ibge__municipio_anual.csv","rendimento_medio_kg_ha","soja"),
        ("h1_h2__ppm_bovinos__ibge__municipio_anual.csv","efetivo_bovino",None)]:
        source=pd.read_csv(base/file,encoding="utf-8-sig",low_memory=False)
        if product:
            source=source.loc[source.produto.str.lower().str.startswith(product)].copy()
            column=next(c for c in pt if c.startswith("rendimento_medio_kg_ha__"+product.title()))
            gcolumn=f"rend_{product}_kg_ha"
        else:
            column=gcolumn="efetivo_bovino"
        for key in KEY: source[key]=pd.to_numeric(source[key],errors="raise").astype("int64")
        assert not source.duplicated(KEY).any(),f"Fonte nao unica {file} {product}"
        aligned=pt[KEY].merge(source[KEY+[value]],on=KEY,how="left",validate="one_to_one")
        for label,panel,col in [("PT",pt,column),("GM",gm,gcolumn)]:
            result["originais"].append({"base":label,"coluna":col,"fonte":str((base/file).relative_to(root)),
                                        **compare(panel[col],aligned[value],exact=True)})
    ptcopy=root/"2_INTI/xdata/chap1/processed/harmonizacao/painel_notebook/paineis/painel_tese_chap1_pt.csv"
    gmcopy=root/"2_INTI/chapters/chap1/stats/AED/gm/painel_mt_2001_2024.csv"
    result["linhagem"]["pt_copia_identica_bytes"]=digest(ptcopy)==digest(here/"painel_tese_chap1_pt.csv")
    canonical=load(gmcopy).sort_values(KEY).reset_index(drop=True)
    assert canonical[KEY].equals(gm[KEY]) and list(canonical)==list(gm)
    diffs={c:compare(gm[c],canonical[c],exact=True) for c in gm}
    result["linhagem"]["gm_todas_colunas_iguais_apos_chave"]=all(v["dif_exatas"]==0 and v["ausencia_xor"]==0 for v in diffs.values())
    result["linhagem"]["gm_copia_mesmos_bytes"]=digest(gmcopy)==digest(here/"painel_tese_chap1_gm.csv")
    bio=pd.read_csv(base/"h2__biome_share__ibge2019_malha2024__candidato.csv",encoding="utf-8-sig")
    source_rows=bio.loc[bio.codigo_ibge.isin([5101837,5106240])]
    cols=["codigo_ibge","municipio","biome_amazonia_share_i","biome_cerrado_share_i","biome_pantanal_share_i","biome_class_70"]
    result["territorio"]["fonte_biomas"]=source_rows[cols].to_dict("records")
    result["territorio"]["gm_codigo_5106240"]=gm.loc[gm.codigo_ibge.eq(5106240),cols].drop_duplicates().to_dict("records")
    result["territorio"]["pt_codigo_5106240"]=pt.loc[pt.codigo_ibge.eq(5106240),[c for c in cols if c in pt]].drop_duplicates().to_dict("records")
    stocks=pd.read_csv(base/"h1_h2__mapbiomas_classes__col10_1__municipio_bioma_anual.csv",encoding="utf-8-sig",low_memory=False)
    cotton=stocks.loc[stocks.class_id.eq(62)].groupby(KEY,as_index=False).area_ha.sum()
    cotton=pt[KEY].merge(cotton,on=KEY,how="left",validate="one_to_one")
    missing62=cotton.area_ha.isna()
    delta_ag=pt.agricultura_ha-gm.estoque_agricultura_ha
    result["classes_agricultura"]={"pt":[20,35,39,40,41,46,47,48,62],"gm":[20,39,41],
        "teste_pt_menos_gm_vs_classe62_somente_linhas_observadas":compare(delta_ag,cotton.area_ha),
        "pares_com_classe62_positiva":int(cotton.area_ha.gt(0).sum()),
        "pares_sem_linha_classe62":int(missing62.sum()),
        "pares_sem_linha62_com_diferenca_estoque_zero_na_tolerancia":int((delta_ag[missing62].abs() <= ATOL+RTOL*np.maximum(pt.agricultura_ha[missing62].abs(),gm.estoque_agricultura_ha[missing62].abs())).sum()),
        "nota":"Sem imputar valores a classe62: igualdade testada apenas onde ha linha da fonte; diferenca zero nos demais e propriedade dos paineis, nao observacao direta de area zero da classe."}
    result["diagnostico_y_agregado"]={
        "fluxos_pt_somados_vs_incrementos_gm":compare(pt.conversao_ha__agricultura+pt.conversao_ha__pastagem,gm.Y_conv_total_ha),
        "taxas_pt_somadas_vs_taxa_gm":compare(pt.taxa_conversao__agricultura+pt.taxa_conversao__pastagem,gm.Y_tx_conv),
        "nota":"Soma apenas para diagnostico entre objetos distintos, sem modificar paineis/requisito por destino; operador + preserva NA; equivalencia conceitual rejeitada (e)."}
    raw=root/"2_INTI/xdata/chap1/raw/tabular/ibama/termo_embargo_historico.csv"
    count=Counter(); rows=cancel=release=release_date=0
    cols=["UF","SEQ_TAD","SIT_CANCELADO","SIT_DESEMBARGO","DAT_DESEMBARGO"]
    for chunk in pd.read_csv(raw,sep=";",encoding="utf-8-sig",usecols=cols,dtype="string",chunksize=100000):
        mt=chunk.loc[chunk.UF.eq("MT")]
        rows+=len(mt); count.update(mt.SEQ_TAD.dropna().astype(str))
        cancel+=int(mt.SIT_CANCELADO.eq("S").sum())
        release+=int(mt.SIT_DESEMBARGO.eq("S").sum())
        release_date+=int(mt.DAT_DESEMBARGO.notna().sum())
    result["historico_embargos"]={"linhas_mt":rows,"termos_distintos_nao_ausentes":len(count),
        "linhas_de_termos_repetidos":sum(v for v in count.values() if v>1),
        "max_historicos_por_termo":max(count.values(),default=0),"linhas_canceladas":cancel,
        "linhas_desembargadas":release,"linhas_data_desembargo":release_date,
        "limite":"Estatistica de linhas historicas, nao contagem/area de embargos ativos; GM ignora estes IDs/status."}
    return result


def coverage(df, columns):
    present=[c for c in columns if c in df]
    if not present: return {"n":0,"municipios":0,"n_2021_2024":0,"any":0,"faltantes":columns}
    mask=df[present].notna().all(axis=1)
    if len(present)!=len(columns): mask[:]=False
    return {"n":int(mask.sum()),"municipios":int(df.loc[mask,"codigo_ibge"].nunique()),
            "n_2021_2024":int((mask & df.ano.between(2021,2024)).sum()),
            "any":int(df[present].notna().any(axis=1).sum()),"faltantes":[c for c in columns if c not in df]}


def esc(value):
    if value is None: return "—"
    if isinstance(value,(list,dict)): value=json.dumps(value,ensure_ascii=False)
    return str(value).replace("|","\\|").replace("\n","<br>").replace("\r","")


def table(headers, rows):
    return "\n".join(["| "+" | ".join(map(esc,headers))+" |", "| "+" | ".join(["---"]*len(headers))+" |"]+["| "+" | ".join(map(esc,row))+" |" for row in rows])+"\n"


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--testes-apenas",action="store_true",help="Recalcula JSON/CSV em audit, preservando relatorio MD")
    args=parser.parse_args()
    here=Path(__file__).resolve().parent
    root=next(p for p in here.parents if (p/"2_INTI/RESEARCH_PROTOCOL.md").exists())
    out=root/"2_INTI/audit/comparacao_aed_pt_gm_chap1"
    out.mkdir(parents=True,exist_ok=True)
    paths={k:here/f"painel_tese_chap1_{k.lower()}.csv" for k in ["PT","GM"]}
    hypothesis=root/"2_INTI/chapters/chap1/stats/HIPOTESES TESE - CHAP1.txt"
    protected=list((root/"2_INTI/chapters/chap1/stats/AED").rglob("*.py"))+list((root/"2_INTI/chapters/chap1/stats/AED").rglob("*.ipynb"))+list(paths.values())+[hypothesis]
    source_base=root/"2_INTI/xdata/chap1/processed/tabular"
    protected += [source_base/name for name in ["h1_h2__pam_soja_milho__ibge__municipio_anual.csv","h1_h2__ppm_bovinos__ibge__municipio_anual.csv","h2__biome_share__ibge2019_malha2024__candidato.csv","h1_h2__mapbiomas_classes__col10_1__municipio_bioma_anual.csv"]]
    protected += [root/"2_INTI/xdata/chap1/raw/tabular/ibama/termo_embargo_historico.csv",root/"2_INTI/xdata/chap1/processed/harmonizacao/painel_notebook/paineis/painel_tese_chap1_pt.csv",root/"2_INTI/chapters/chap1/stats/AED/gm/painel_mt_2001_2024.csv"]
    protected=sorted(set(protected))
    protected=[p for p in protected if p.resolve()!=Path(__file__).resolve()]
    before={str(p.relative_to(root)).replace("\\","/"):digest(p) for p in protected}
    frames={k:load(p) for k,p in paths.items()}
    structural={}
    for k,df in frames.items():
        structural[k]={"linhas":len(df),"colunas":len(df.columns),"municipios":df.codigo_ibge.nunique(),
                       "anos":sorted(df.ano.unique().tolist()),"duplicadas_chave":int(df.duplicated(KEY).sum()),
                       "balanceado":len(df)==df.codigo_ibge.nunique()*df.ano.nunique(),
                       "tipos":df.dtypes.astype(str).value_counts().to_dict(),
                       "uf_51":bool(df.codigo_ibge.astype(str).str.startswith("51").all()),
                       "codigos_7_digitos":bool(df.codigo_ibge.astype(str).str.len().eq(7).all()),
                       "colunas_caractere_substituicao":[c for c in df if "\ufffd" in c]}
    outer=frames["PT"][KEY].merge(frames["GM"][KEY],on=KEY,how="outer",validate="one_to_one",indicator=True)
    align={"chave":KEY,"outer_linhas":len(outer),"cobertura_chaves":outer._merge.value_counts().to_dict(),
           "mesma_ordem_original":frames["PT"][KEY].equals(frames["GM"][KEY]),
           "codigos_so_pt":sorted(set(frames["PT"].codigo_ibge)-set(frames["GM"].codigo_ibge)),
           "codigos_so_gm":sorted(set(frames["GM"].codigo_ibge)-set(frames["PT"].codigo_ibge))}
    assert len(outer)==len(frames["PT"])==len(frames["GM"]),"Chaves distintas; adaptar auditoria explicitamente"
    aligned={k:df.sort_values(KEY).reset_index(drop=True) for k,df in frames.items()}
    assert aligned["PT"][KEY].equals(aligned["GM"][KEY])
    profiles={k:profile(df) for k,df in aligned.items()}
    pairs=pair_results(aligned["PT"],aligned["GM"])
    scanned,hits=numerical_scan(aligned["PT"],aligned["GM"],pairs)
    formulas=formula_tests(aligned["PT"],aligned["GM"])
    sources=source_tests(root,here,aligned["PT"],aligned["GM"])
    requirements=EVIDENCE.get("requirements",[])
    requirement_coverage=[]
    for req in requirements:
        item=dict(req)
        for k in ["PT","GM"]:
            item[f"cobertura_{k.lower()}"]=coverage(aligned[k],req[f"{k.lower()}_columns"])
        requirement_coverage.append(item)
    # Prova de invariancia a ordem por uma permutacao deterministica da GM.
    shuffled=frames["GM"].sample(frac=1,random_state=20261015).sort_values(KEY).reset_index(drop=True)
    assert shuffled.equals(aligned["GM"])
    # Asserts tecnicos nao certificam a validade substantiva das formulas.
    assert len(profiles["PT"])==296 and len(profiles["GM"])==91
    assert all(v["infinitos"]==0 for d in profiles.values() for v in d.values())
    for k in frames:
        write_json(out/f"perfil_{k.lower()}.json",profiles[k])
        cov=[]
        for c in aligned[k]:
            for year,g in aligned[k].groupby("ano"):
                cov.append({"coluna":c,"ano":int(year),"validos":int(g[c].notna().sum()),"ausentes":int(g[c].isna().sum())})
        pd.DataFrame(cov).to_csv(out/f"cobertura_por_ano_{k.lower()}.csv",index=False,encoding="utf-8-sig")
        mun=[]
        for c in aligned[k]:
            for code,g in aligned[k].groupby("codigo_ibge"):
                mun.append({"coluna":c,"codigo_ibge":int(code),"anos_validos":int(g[c].notna().sum()),"anos_ausentes":int(g[c].isna().sum())})
        pd.DataFrame(mun).to_csv(out/f"cobertura_por_municipio_{k.lower()}.csv",index=False,encoding="utf-8-sig")
    write_json(out/"estrutura_alinhamento.json",{"estrutura":structural,"alinhamento":align})
    write_json(out/"correspondencias.json",pairs)
    write_json(out/"coincidencias_numericas.json",{"pares_testados":scanned,"coincidencias":hits})
    write_json(out/"testes_formulas.json",formulas)
    write_json(out/"testes_fontes_locais.json",sources)
    write_json(out/"matriz_hipoteses_recalculada.json",requirement_coverage)
    joint=[{"base":x["base"],"colunas":x["columns"],"cobertura":coverage(aligned[x["base"].upper()],x["columns"])} for x in EVIDENCE.get("joint_illustrations",[])]
    write_json(out/"cobertura_conjunta_ilustrativa.json",joint)
    pd.DataFrame(pairs).to_csv(out/"correspondencias.csv",index=False,encoding="utf-8-sig")
    # Inventario editorial (incorporado apos rastreamento humano) + perfil observado.
    inventory={}
    for k in frames:
        meta=EVIDENCE.get(k,{})
        inventory[k]={c:{**meta.get(c,{"origem":"origem indeterminada","descricao":"Evidencia editorial ainda nao incorporada","unidade":"nao comprovada","grupo":"G5"}),**profiles[k][c]} for c in frames[k]}
    if EVIDENCE:
        assert set(EVIDENCE["PT"])==set(frames["PT"]) and set(EVIDENCE["GM"])==set(frames["GM"])
        for k in frames:
            assert all(v.get("grupo") in ["G1","G2","G3","G4","G5"] for v in inventory[k].values())
    write_json(out/"inventario_completo.json",inventory)
    if not args.testes_apenas:
        report=make_report(root,here,structural,align,inventory,pairs,hits,scanned,formulas,before,aligned,requirement_coverage,sources)
        (here/"comparacao_aed_pt-gm_chap1.md").write_text(report,encoding="utf-8")
    after={str(p.relative_to(root)).replace("\\","/"):digest(p) for p in protected}
    assert before==after,"Algum insumo protegido mudou durante auditoria"
    write_json(out/"manifesto_execucao.json",{"data_referencia":"2026-10-15","python":sys.version,"executavel":sys.executable,
               "pandas":pd.__version__,"numpy":np.__version__,"plataforma":platform.platform(),
               "tolerancias":{"atol":ATOL,"rtol":RTOL,"regra":"abs(a-b)<=atol+rtol*max(abs(a),abs(b)); categorias/chaves/contagens exatas"},
               "hashes_antes":before,"hashes_depois":after,"preservados":before==after,
               "script_sha256":digest(Path(__file__)),"testes":["cabecalhos unicos","chave integral sem NA e unica","outer one_to_one","mesma grade","permutacao de linhas","inventario reconciliado","sem infinitos","hashes protegidos"],
               "pares_numericos_testados":scanned})
    print(json.dumps(clean({"estrutura":structural,"alinhamento":align,"categorias":dict(Counter(r["categoria"] for r in pairs)),
          "pares_numericos":scanned,"coincidencias":len(hits),"formulas":formulas,"protegidos":len(before),"preservados":True}),ensure_ascii=False,indent=2))


def make_report(root,here,structural,align,inventory,pairs,hits,scanned,formulas,hashes,aligned,requirements,sources):
    # Texto consolidado e matriz de requisitos sao acrescentados no catalogo incorporado.
    parts=["# Auditoria comparativa AED PT–GM — capítulo 1\n\nData de referência: 15/10/2026. Evidências exclusivamente locais.\n",
           EVIDENCE.get("resumo","Relatorio em preparacao."),"\n## Validação e alinhamento\n",
           table(["Base (nome do arquivo)","Linhas","Colunas","Municípios","Anos","Chave duplicada","Balanceado"],[[k,s["linhas"],s["colunas"],s["municipios"],f'{min(s["anos"])}–{max(s["anos"])}',s["duplicadas_chave"],s["balanceado"]] for k,s in structural.items()]),
           f"Chave: `codigo_ibge, ano`. Junção externa `validate='one_to_one'`: {align['outer_linhas']} linhas; {esc(align['cobertura_chaves'])}. Mesma ordem original: {align['mesma_ordem_original']}. Os testes usam ordenação pela chave e conferência explícita das chaves, inclusive após permutação determinística. A grade de códigos coincide; isso não comprova identidade das geometrias das fontes.\n",
           "\n### Estrutura e tipos observados\n",table(["Base","Tipos inferidos","Problemas de codificação nos nomes"],[[k,s["tipos"],s["colunas_caractere_substituicao"]]for k,s in structural.items()]),
           EVIDENCE.get("metodologia",""),EVIDENCE.get("fontes",""),"\n## Contagens reconciliadas\n"]
    for k,meta in inventory.items():
        cats=Counter(v.get("origem","origem indeterminada") for v in meta.values())
        cats={c:cats.get(c,0) for c in ["identificador","original","derivada","origem indeterminada"]}
        groups=Counter(v.get("grupo","G5") for v in meta.values())
        groups={g:groups.get(g,0) for g in ["G1","G2","G3","G4","G5"]}
        assert sum(cats.values())==len(meta)==structural[k]["colunas"]
        parts += [f"\n### {k}\n",table(["Origem","Colunas"],list(cats.items())+[["TOTAL",len(meta)]]),table(["Grupo de adequação (atribuição primária única)","Colunas"],list(groups.items())+[["TOTAL",len(meta)]])]
    parts += ["\nG1: requisito direto. G2: insumo para construção. G3: proxy/alternativa com limites. G4: sem vínculo substantivo identificado (inclui chaves, metadados e diagnósticos auxiliares). G5: insuficiência de evidência. A atribuição primária serve exclusivamente à reconciliação; vínculos múltiplos constam do inventário, sem contar a coluna novamente. Flags podem ser essenciais ao uso seguro sem constituir regressoras requeridas.\n",
              "\n## Equivalências e diferenças\n",EVIDENCE.get("comparacao_texto",""),
              "Categorias: a = mesmo conceito e valores/padrão NA iguais; b = equivalência após transformação documentada; c = mesmo conceito com valores, cobertura ou tratamento diferentes; d = coincidência numérica sem conceito comprovado; e = exclusiva, correspondência indeterminada ou correspondência conceitual rejeitada. A relação PT Y bruta × GM incremento de estoque é rejeitada (e), com quantificação das diferenças, pois fluxo de origem nativa e aumento líquido positivo são objetos distintos. Tolerância simétrica: `abs(a-b) <= 1e-8 + 1e-9*max(abs(a),abs(b))`. Chaves/categorias/contagens são exatas. Diferenças exatas menores que a tolerância continuam informadas. Não foram calculadas correlações para declarar igualdade.\n",
              table(["Cat.","PT","GM","Conceito / transformação em PT","N comparável","Dif. exatas","Dif. tolerância","Só PT presente","Só GM presente","Máx. abs.","Evidência PT / GM"],[[r["categoria"],r["pt"],r["gm"],r["conceito"]+f' [{r["modo"]}; fator={r["fator"]}]',r["comparaveis"],r["dif_exatas"],r["dif_tolerancia"],r["so_a_presente"],r["so_b_presente"],r["max_abs"],str(inventory["PT"][r["pt"]].get("evidencia",""))+" / "+str(inventory["GM"][r["gm"]].get("evidencia",""))]for r in pairs]),
              f"\nBusca numérica exaustiva: {scanned} pares numéricos, {len(hits)} coincidências sobre a interseção não ausente. A busca não prova conceito, descarta pares sem qualquer valor comum e mantém flags/constantes identificadas como evidência insuficiente. Detalhes integrais em `2_INTI/audit/comparacao_aed_pt_gm_chap1/coincidencias_numericas.json`.\n"]
    parts += ["\nContagem das correspondências conceituais testadas: "+esc(dict(Counter(r["categoria"] for r in pairs)))+f"; total {len(pairs)} pares. São pares, não contagens de colunas únicas. A lista de categoria e abaixo completa as colunas sem correspondência direta testada.\n"]
    unexplained=[r for r in hits if not r["mapeado"]]
    parts += ["\n### Coincidências sem equivalência comprovada (d)\n",table(["PT","GM","N comparável","Dif. exatas","Dif. NA","Distintos PT/GM","Evidência numérica insuficiente"],[[r["pt"],r["gm"],r["comparaveis"],r["dif_exatas"],r["ausencia_xor"],f'{r["distintos_a_comuns"]}/{r["distintos_b_comuns"]}',r["evidencia_insuficiente"]] for r in unexplained])]
    for k in ["PT","GM"]:
        mapped={r[k.lower()] for r in pairs}
        exclusive=[c for c in inventory[k] if c not in mapped]
        parts += [f"\n### {k}: sem correspondência direta testada (e)\n\nNão significa que sejam conceitos inéditos: inclui variantes, diagnósticos e construções exclusivas; a relação substantiva é registrada no inventário.\n\n"+", ".join(f"`{c}`" for c in exclusive)+".\n"]
    parts += ["\n## Testes de fórmulas e tratamentos\n",table(["Base","Teste","N comparável","Dif. tolerância","Dif. NA","Resultado"],[[r["base"],r["teste"],r["comparaveis"],r["dif_tolerancia"],r["ausencia_xor"],r["resultado"]]for r in formulas]),EVIDENCE.get("divergencias",""),EVIDENCE.get("hipoteses_texto","")]
    parts += ["\n### Matriz H1: 25 candidatos textuais\n\nCada cobertura conjunta desta tabela exige valores em todas as colunas listadas na célula da base. É uma descrição reproduzível, não uma especificação: os cenários/produtos são alternativas. O segundo N corresponde ao cabeçalho 2021–2024 (564 pares potenciais), sem substituir o recorte candidato 2001–2024. Ausência de colunas é informada separadamente.\n",
              table(["Requisito textual / linhas TXT","Papel","PT / grupo","GM / grupo","Unidade","Transformação/defasagem","Cobertura PT: N / mun / N2021–24","Cobertura GM: N / mun / N2021–24","Limitações / evidência"],
              [[r["id"]+" (L"+r["lines"]+"): "+r["textual_requirement"],r["role"],str(r["pt_columns"])+"; "+r["group_pt"],str(r["gm_columns"])+"; "+r["group_gm"],r["unit"],r["adjustment_or_lag"],f'{r["cobertura_pt"]["n"]} / {r["cobertura_pt"]["municipios"]} / {r["cobertura_pt"]["n_2021_2024"]}',f'{r["cobertura_gm"]["n"]} / {r["cobertura_gm"]["municipios"]} / {r["cobertura_gm"]["n_2021_2024"]}',r["limitations"]+"; "+str(r["evidence"])]for r in requirements]),
              "\n### Verificações contra fontes processadas locais\n",table(["Base","Coluna","Fonte","N comparável","Dif. exatas","Dif. NA"],[[r["base"],r["coluna"],r["fonte"],r["comparaveis"],r["dif_exatas"],r["ausencia_xor"]]for r in sources["originais"]]),
              "\nLinhagem: "+esc(sources["linhagem"])+". Identidade do arquivo não autentica o fornecedor externo.\n",
              "\nTeste de classes agrícolas: "+esc(sources["classes_agricultura"])+".\n",
              "\nComparação diagnóstica dos totais Y (categoria e; destinos preservados no painel): "+esc(sources["diagnostico_y_agregado"])+".\n",
              "\nDiagnóstico do histórico de embargos: "+esc(sources["historico_embargos"])+".\n",
              "\nTerritório: "+esc(sources["territorio"])+".\n"]
    parts += ["\n### Elementos textuais adicionais\n",table(["Elemento","Linhas / requisito textual","PT","GM","Ajuste / limite"],[[r["id"],str(r["textual"]),r.get("pt",""),r.get("gm",""),str(r.get("ajuste",""))+"; "+str(r.get("limites",""))]for r in EVIDENCE.get("non_column_requirements",[])]),
              "\n### Cobertura conjunta ilustrativa do núcleo\n\nInterseções diagnósticas, sem escolher modelo. Exigem Y por ambos destinos, preços de soja/milho nas transformações listadas, uma capacidade e uma medida institucional. Valores presentes em GM não corrigem a inadequação conceitual de Y nem legitimam zeros imputados.\n",
              table(["Base","Colunas exigidas","N 2001–24","Municípios","N 2021–24"],[[x["base"],x["columns"],coverage(aligned[x["base"].upper()],x["columns"])["n"],coverage(aligned[x["base"].upper()],x["columns"])["municipios"],coverage(aligned[x["base"].upper()],x["columns"])["n_2021_2024"]]for x in EVIDENCE.get("joint_illustrations",[])])]
    parts += ["\n## Inventário completo\n\nUma linha por coluna na ordem original. Cobertura = valores não ausentes, municípios com pelo menos um valor, anos com pelo menos um valor e intervalo observado; o intervalo não afirma continuidade. Cobertura detalhada por ano está nos CSVs de auditoria. NAs não foram substituídos por zero. `dtype` é a inferência de leitura do CSV, que não armazena esquema.\n"]
    for k,meta in inventory.items():
        parts += [f"\n### Inventário {k} — {len(meta)} colunas\n",table(["#","Nome","Descrição / unidade","Fonte e período/versão","Origem","Fórmula / entradas","Evidência local","Grupo / vínculos / limite","Tipo; NA; cobertura"],
            [[i,c,str(v.get("descricao","não comprovada"))+" / "+str(v.get("unidade","não comprovada")),str(v.get("fonte","não comprovada"))+"; "+str(v.get("versao_periodo","período não comprovado")),v.get("origem","origem indeterminada"),str(v.get("formula","não aplicável ou não comprovada"))+"; entradas: "+str(v.get("variaveis_entrada",v.get("entradas","não comprovadas"))),v.get("evidencia","não localizada"),str(v.get("grupo","G5"))+"; "+str(v.get("vinculos",""))+"; "+str(v.get("limitacoes","")),f'{v["dtype"]}; {v["ausentes"]}/{structural[k]["linhas"]} ({100*v["proporcao_ausente"]:.4f}%); N={v["validos"]}; mun={v["municipios_com_valor"]}; anos={v["anos_com_valor"]} ({v["ano_min"]}–{v["ano_max"]}); distintos={v["distintos"]}']for i,(c,v) in enumerate(meta.items(),1)])]
    parts += [EVIDENCE.get("conclusao",""),"\n## Reprodução, preservação e continuidade\n\nExecutar na raiz do repositório:\n\n```powershell\n& '2_INTI/audit/aed_chap1_20261013/venv/Scripts/python.exe' '2_INTI/chapters/chap1/stats/EDA/paineis/auditoria_comparativa_aed_pt_gm_chap1.py'\n```\n\nO script incorpora as decisões de rastreabilidade e recalcula as estatísticas. Não importa módulos de produção nem executa notebooks. `--testes-apenas` atualiza somente os artefatos técnicos. Os arquivos de evidência não constituem comprovação externa da qualidade da fonte. Se os insumos mudarem, reavaliar o catálogo editorial e as hipóteses antes de usar o relatório regenerado.\n\n",
              f"Hashes SHA-256 de {len(hashes)} arquivos de produção, notebooks, painéis e hipóteses foram conferidos antes/depois; ver `manifesto_execucao.json`. O manifesto inclui versões, executável, tolerâncias e hash do auxiliar. Logs, perfis, cobertura por ano, correspondências, coincidências, inventário estruturado e testes de fórmulas ficam em `2_INTI/audit/comparacao_aed_pt_gm_chap1/`. Nenhum pipeline foi reexecutado. Não houve instalação, commit, merge ou push. A saída principal e o auxiliar ficam junto dos painéis por solicitação expressa, prevalecendo sobre a convenção geral de armazenamento.\n"]
    return "\n".join(parts)


